const raw = $input.first().json || {};
const payload = raw.body && typeof raw.body === 'object' ? raw.body : raw;

let memberId = '';
let amountPaid = 0;
let transactionRef = '';
let paymentMode = 'UPI';
let planOverride = '';
let source = 'direct';

if (payload.event === 'payment_link.paid' && payload.payload?.payment_link?.entity) {
  const entity = payload.payload.payment_link.entity;
  memberId = String(entity.reference_id || '').trim();
  amountPaid = Number(entity.amount_paid || entity.amount || 0) / 100;
  transactionRef = String(entity.id || '').trim();
  paymentMode = 'Razorpay';
  source = 'razorpay_webhook';
} else {
  memberId = String(payload.member_id || '').trim();
  amountPaid = Number(payload.amount_paid ?? payload.amount ?? 0);
  transactionRef = String(payload.transaction_ref || payload.reference || `MANUAL-${Date.now()}`).trim();
  paymentMode = String(payload.payment_mode || 'UPI').trim();
  planOverride = String(payload.plan || '').trim();
  source = String(payload.source || 'fastapi_backend').trim();
}

if (!memberId) {
  throw new Error('Missing member_id in payment webhook payload.');
}
if (!Number.isFinite(amountPaid) || amountPaid <= 0) {
  throw new Error('Payment amount_paid must be a positive number.');
}

return [{
  json: {
    member_id: memberId,
    amount_paid: amountPaid,
    transaction_ref: transactionRef,
    payment_mode: paymentMode,
    plan_override: planOverride,
    source,
  },
}];

const PLAN_DURATIONS = {
  Monthly: 30,
  Quarterly: 90,
  'Half-Yearly': 180,
  Yearly: 365,
};

const pay = $('Code - Parse & Validate Payment').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r.member_id);

if (rows.length === 0) {
  throw new Error(`Member not found for member_id=${pay.member_id}`);
}

const row = rows[0];
const today = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).format(new Date());

const existingNotes = String(row.notes || '');
const refMarker = `Ref:${pay.transaction_ref}`;
if (existingNotes.includes(refMarker)) {
  return [{
    json: {
      already_processed: true,
      member_id: row.member_id,
      member_name: row.name,
      message: `Duplicate webhook ignored for ${refMarker}`,
      expiry_date: row.expiry_date,
      payment_status: row.payment_status,
    },
  }];
}

function addDays(isoDate, days) {
  const [y, m, d] = isoDate.split('-').map(Number);
  const utcMs = Date.UTC(y, m - 1, d) + days * 86400000;
  const dt = new Date(utcMs);
  return `${dt.getUTCFullYear()}-${String(dt.getUTCMonth() + 1).padStart(2, '0')}-${String(dt.getUTCDate()).padStart(2, '0')}`;
}

const activePlan = pay.plan_override && PLAN_DURATIONS[pay.plan_override] ? pay.plan_override : (row.plan || 'Monthly');
const durationDays = PLAN_DURATIONS[activePlan] || 30;
const isFirstPayment = !String(row.last_payment_date || '').trim();
const baseDate = String(row.expiry_date || '') > today ? String(row.expiry_date) : today;
const newExpiry = isFirstPayment && String(row.expiry_date || '').trim() ? String(row.expiry_date) : addDays(baseDate, durationDays);

const stamp = Date.now().toString(36).toUpperCase().slice(-6);
const paymentId = `PAY-${stamp}`;
const invoiceNumber = `INV-${today.replace(/-/g, '')}-${stamp.slice(-4)}`;
const updatedNotes = existingNotes ? `${existingNotes} | Paid:${today} ${refMarker}` : `Paid:${today} ${refMarker}`;

return [{
  json: {
    already_processed: false,
    payment_id: paymentId,
    invoice_number: invoiceNumber,
    member_id: row.member_id,
    member_name: row.name,
    phone: row.phone,
    plan: activePlan,
    amount_paid: pay.amount_paid,
    payment_mode: pay.payment_mode,
    transaction_ref: pay.transaction_ref,
    payment_date: today,
    new_expiry_date: newExpiry,
    payment_status: 'Paid',
    member_status: 'Active',
    notes_update: updatedNotes,
    status: 'Confirmed',
  },
}];
